$files = Get-ChildItem -File | Where-Object { $_.Name -notmatch '\.ps1$' -and $_.Name -notmatch 'done\.txt' }
if (-not (Test-Path Compressed)) { New-Item -ItemType Directory -Path Compressed | Out-Null }

$pool = [runspacefactory]::CreateRunspacePool(1, 10)
$pool.Open()
$jobs = @()

foreach ($file in $files) {
    $job = [powershell]::Create().AddScript({
        param($f)
        $out = "Compressed\$($f.Name)"
        if ($f.Extension -match '\.mp4$|\.mov$|\.avi$') {
            # Video compression
            $cmd = "ffmpeg -y -v quiet -i `"$($f.FullName)`" -c:v libx264 -crf 28 -preset veryfast -c:a aac -b:a 128k `"$out`""
            Invoke-Expression $cmd
        } else {
            # Image compression
            $cmd = "ffmpeg -y -v quiet -i `"$($f.FullName)`" -q:v 5 `"$out`""
            Invoke-Expression $cmd
        }
        return $f.Name
    }).AddArgument($file)

    $job.RunspacePool = $pool
    $jobs += [PSCustomObject]@{
        Pipe = $job
        Status = $job.BeginInvoke()
    }
}

while ($jobs.Status.IsCompleted -contains $false) {
    Start-Sleep -Milliseconds 500
}

$pool.Close()
$pool.Dispose()

$origSize = ($files | Measure-Object -Property Length -Sum).Sum
$newFiles = Get-ChildItem -Path Compressed -File
$newSize = ($newFiles | Measure-Object -Property Length -Sum).Sum

[PSCustomObject]@{
    OriginalSizeMB = [math]::Round($origSize / 1MB, 2)
    NewSizeMB = [math]::Round($newSize / 1MB, 2)
    FilesProcessed = $newFiles.Count
} | ConvertTo-Json

$missing = @(
"IMG20260426073923.jpg",
"IMG20260426074534.jpg",
"VID20260805124212.mp4",
"VID20260805124717.mp4",
"VID20260805125134.mp4",
"VID20260805125731.mp4",
"VID20260805143007.mp4",
"VID20260811095516.mp4",
"VID20260811095539.mp4",
"VID20260815180109.mp4",
"VID20260815181946.mp4",
"VID20260819203826.mp4"
)

foreach ($file in $missing) {
    if (Test-Path $file) {
        $out = "Compressed\$file"
        if ($file -match '\.mp4$') {
            $cmd = "ffmpeg -y -v quiet -i `"$file`" -c:v libx264 -crf 28 -preset fast -c:a aac -b:a 128k `"$out`""
            Invoke-Expression $cmd
        } else {
            $cmd = "ffmpeg -y -v quiet -i `"$file`" -q:v 5 `"$out`""
            Invoke-Expression $cmd
        }
    }
}

$allFiles = Get-ChildItem -File | Where-Object { $_.Name -notmatch '\.ps1$' -and $_.Name -notmatch 'done\.txt' }
$origSize = ($allFiles | Measure-Object -Property Length -Sum).Sum
$newFiles = Get-ChildItem -Path Compressed -File
$newSize = ($newFiles | Measure-Object -Property Length -Sum).Sum

[PSCustomObject]@{
    OriginalSizeMB = [math]::Round($origSize / 1MB, 2)
    NewSizeMB = [math]::Round($newSize / 1MB, 2)
    SavedMB = [math]::Round(($origSize - $newSize) / 1MB, 2)
    SavedPercent = [math]::Round((($origSize - $newSize) / $origSize) * 100, 2)
} | ConvertTo-Json | Out-File -FilePath result.json

$sourceDir = "C:\Users\renu5\Downloads\New folder\Instagram"
$destDir = "C:\Users\renu5\Downloads\New folder\Instagram compressed"

if (-not (Test-Path $destDir)) { New-Item -ItemType Directory -Path $destDir | Out-Null }

$files = Get-ChildItem -Path $sourceDir -File
$pool = [runspacefactory]::CreateRunspacePool(1, 4)
$pool.Open()
$jobs = @()

foreach ($file in $files) {
    $job = [powershell]::Create().AddScript({
        param($f, $dest)
        $out = Join-Path $dest $f.Name
        $success = $false
        $failedCount = 0

        for ($i = 0; $i -lt 3; $i++) {
            if ($f.Extension -match '\.mp4$|\.mov$|\.avi$') {
                $cmd = "ffmpeg -y -v quiet -i `"$($f.FullName)`" -c:v libx264 -crf 28 -preset veryfast -c:a aac -b:a 128k `"$out`""
            } else {
                $cmd = "ffmpeg -y -v quiet -i `"$($f.FullName)`" -q:v 5 `"$out`""
            }

            $proc = Start-Process -FilePath "cmd.exe" -ArgumentList "/c $cmd" -Wait -PassThru -NoNewWindow

            if ($proc.ExitCode -eq 0 -and (Test-Path $out) -and (Get-Item $out).Length -gt 0) {
                $success = $true
                break
            } else {
                $failedCount++
                Start-Sleep -Seconds 1
            }
        }

        return [PSCustomObject]@{
            Name = $f.Name
            Success = $success
            Retries = $failedCount
        }
    }).AddArgument($file).AddArgument($destDir)

    $job.RunspacePool = $pool
    $jobs += [PSCustomObject]@{
        Pipe = $job
        Status = $job.BeginInvoke()
    }
}

while ($jobs.Status.IsCompleted -contains $false) {
    Start-Sleep -Seconds 2
}

$results = @()
foreach ($j in $jobs) {
    $results += $j.Pipe.EndInvoke($j.Status)
    $j.Pipe.Dispose()
}

$pool.Close()
$pool.Dispose()

$origSize = ($files | Measure-Object -Property Length -Sum).Sum
$newFiles = Get-ChildItem -Path $destDir -File
$newSize = ($newFiles | Measure-Object -Property Length -Sum).Sum

$initialFails = ($results | Where-Object { $_.Retries -gt 0 }).Count
$totalFails = ($results | Where-Object { $_.Success -eq $false }).Count
$totalSuccess = ($results | Where-Object { $_.Success -eq $true }).Count

[PSCustomObject]@{
    OriginalSizeMB = [math]::Round($origSize / 1MB, 2)
    NewSizeMB = [math]::Round($newSize / 1MB, 2)
    TotalFiles = $files.Count
    InitialFailsAndRetried = $initialFails
    FinalFailed = $totalFails
    TotalSuccess = $totalSuccess
} | ConvertTo-Json | Out-File -FilePath "C:\Users\renu5\Downloads\New folder\insta_result.json"

